def cosine(a: list, b: list) -> float:
    """两个等长向量的余弦相似度（纯 Python，不用 numpy）。
    任一向量模长为 0 时返回 0.0。
    """
    if not a or not b:
        return 0.0
    norm_a_sq = 0.0
    norm_b_sq = 0.0
    dot = 0.0
    for x, y in zip(a, b):
        dot += x * y
        norm_a_sq += x * x
        norm_b_sq += y * y
    if norm_a_sq == 0.0 or norm_b_sq == 0.0:
        return 0.0
    return dot / ((norm_a_sq * norm_b_sq) ** 0.5)

